  "pricing.qTitle": "Bevor du zahlst",
  "pricing.afterQ": "Was passiert nach {days} Tagen?",
  "pricing.afterA": "Der Trip Pass endet. Nichts verlängert sich, nichts wird mehr abgebucht. Deine Reisen bleiben gespeichert und Planen bleibt kostenlos. Exporte und die zusätzlichen Pläne warten auf einen neuen Pass.",
  "pricing.restoreQ": "Ich habe auf einem anderen Gerät bezahlt. Wo ist mein Pass?",
  "pricing.restoreA": "Dein Pass gehört zu deinem Konto, nicht zum Gerät. Melde dich mit dem Konto an, mit dem du bezahlt hast, und er ist da. Immer noch nicht? Schreib an {email}.",
  "pricing.restoreGo": "Meinen Pass neu prüfen",
  "pricing.restoreSignIn": "Anmelden",
  "pricing.restoreDone": "Geprüft. Dein Plan: {name}.",
  "pass.continueAddDays": "{n} Tage hinzufügen, {price}",
  "pass.carryOver": "Deine restlichen Trip-Pass-Tage bleiben erhalten.",
  "pass.current1": "Du hast einen {name} mit noch 1 Tag.",
  "pass.cancellingNote": "Dein Jahresplan endet am {date}. Behalte ihn, dann verlängert er sich wie bisher.",
  "pass.resume": "Jahresplan behalten",
  "account.fqgPlanning": "Planen",
  "account.fqgPrices": "Preise",
  "account.fqgPasses": "Pässe und Zahlung",
  "account.fqgAccount": "Konto und Daten",
  "account.fq.planQ": "Wie plane ich eine Reise?",
  "account.fq.planA": "Öffne den Reiseplaner, wähle Daten und Orte, und Carta ordnet die Stopps und bepreist jedes Bett, jeden Tag und jede Strecke. Der Tagesplaner füllt dann jeden Tag Stunde für Stunde.",
  "account.fq.togetherQ": "Kann ich eine Reise mit Freunden planen?",
  "account.fq.togetherA": "Ja. Wähle in Meine Reisen bei einer Reise Einladen: Wer den Link hat, kann sich anmelden und die Route mitplanen. Ein Link zum Ansehen geht auch ohne Konto.",
  "account.fq.bookQ": "Kann ich über Carta buchen?",
  "account.fq.bookA": "Nein. Carta bepreist und plant die Reise und schickt dich dann zur Airline, zur Bahn oder zum Gastgeber, um dort direkt zu buchen.",
  "account.fq.missingQ": "Mein Ort fehlt. Was nun?",
  "account.fq.missingA": "Der Tagesplaner funktioniert trotzdem: Gib den Ort ein, er schlägt ihn live nach. Der Katalog wächst mit jedem Update.",
  "account.fq.differentQ": "Wie unterscheidet sich Carta von Google Maps oder Wanderlog?",
  "account.fq.differentA": "Google Maps bringt dich hin und Wanderlog bewahrt den Plan, den du selbst eingetippt hast, aber keine der beiden weiß, was ein Bett oder ein Tag kostet. Carta plant die ganze Reise an einem Ort, mit dem, was jeder Tag kostet: ein Bett plus Essen und Trinken, bepreist für jeden Ort. Carta navigiert nie, deshalb öffnet sich jeder Tag und jede Fahrt in Google Maps.",
  "account.fq.dayQ": "Was steckt im Preis pro Tag?",
  "account.fq.dayA": "Eine Person, ein Tag: ein Bett für die Nacht plus Essen und Trinken (ein Essen im Restaurant, ein schnelles Essen, Getränke), nach deinem Lifestyle. Nicht enthalten: die Anreise, Nahverkehr und Eintritte.",
  "account.fq.estQ": "Warum steht bei einem Preis gesch.?",
  "account.fq.estA": "Es ist eine Schätzung: Die Preise des Orts wurden nicht gemessen, also nimmt Carta das Niveau des Landes. Ein gemessener Preis hat kein Zeichen.",
  "account.fq.lifestyleQ": "Warum änderten sich die Preise, als ich den Lifestyle änderte?",
  "account.fq.lifestyleA": "Weil es deine Preise sind. Ein Schlafsaalbett und eine ganze Wohnung mit Essen auswärts sind verschiedene Reisen, und eine Einstellung steuert jede Zahl in der App.",
  "account.fq.flightsQ": "Zeigt Carta Flugpreise?",
  "account.fq.flightsA": "Ja. Carta zeigt den günstigsten Flug von Google Flights für deine Tage, mit Airline, Zeiten und Prüfzeitpunkt, dazu die übliche Gepäckgebühr als Schätzung. Ein Ticket, das du einträgst, ersetzt ihn.",
  "account.fq.addsQ": "Was bringt ein Pass?",
  "account.fq.addsA": "Kostenlos bleiben {freePlans} Pläne vom Carta-Bot und eine gespeicherte Reise. Ein Trip Pass bringt Export als PDF, Kalender und Karte, alle Reisen gespeichert, das Auslesen von Buchungen, mehr Tagespläne vom Carta-Bot und Live-Suchen nach Events und Öffnungszeiten. Eine Reise teilen und mit Freunden planen bleibt kostenlos.",
  "account.fq.differenceQ": "Was ist der Unterschied zwischen Trip Pass und Jahresplan?",
  "account.fq.differenceA": "Der Trip Pass kostet einmalig {tripPrice} und gilt {tripDays} Tage, ohne Verlängerung. Der Jahresplan kostet {yearPrice} pro Jahr und verlängert sich, bis du kündigst.",
  "account.fq.cancelQ": "Wie kündige ich den Jahresplan?",
  "account.fq.cancelA": "Wähle in Konto unter Dein Plan die Option Jahresplan kündigen. Er läuft bis zum Ende des bezahlten Jahres, danach wird nichts mehr abgebucht.",
  "account.fq.refundQ": "Bekomme ich mein Geld zurück?",
  "account.fq.refundA": "Ja, innerhalb von 14 Tagen nach der Zahlung, wenn du Pass oder Plan nicht genutzt hast. Schreib an {email} von der Adresse deines Kontos.",
  "account.fq.needQ": "Brauche ich ein Konto?",
  "account.fq.needA": "Nicht zum Stöbern oder Planen. Ein Konto hält deine Reisen auf jedem Gerät bereit, öffnet den Carta-Bot und lässt dich mit Freunden planen.",
  "account.fq.whereQ": "Wo werden meine Reisen gespeichert?",
  "account.fq.whereA": "In deinem Konto, wenn du angemeldet bist, also auf jedem Gerät. Abgemeldet bleiben sie in diesem Browser.",
  "account.fq.deleteQ": "Wie lösche ich mein Konto und meine Daten?",
  "account.fq.deleteA": "Öffne in Konto Deine Daten und wähle Mein Konto löschen. Alles verschwindet sofort von Cartas Servern; vorher kannst du eine Kopie herunterladen.",
  "account.faqSearch": "Fragen durchsuchen",
